mapper.select:
SELECT c.cart_id, c.member_id, c.guest_id, c.product_id, c.weight_gram, c.quantity, c.created_at, c.updated_at FROM cart c WHERE c.product_id = #{productId} AND c.weight_gram = #{weightGram}
AND c.member_id = #{memberId}
AND c.guest_id = #{guestId} AND c.member_id IS NULL

mapper.update:
UPDATE cart
SET quantity = quantity + #{quantity},
updated_at = CURRENT_TIMESTAMP
WHERE cart_id = #{cartId}


        AND member_id = #{memberId}


        AND guest_id = #{guestId}
        AND member_id IS NULL

UPDATE cart
SET quantity = #{quantity},
updated_at = CURRENT_TIMESTAMP
WHERE cart_id = #{cartId}


        AND member_id = #{memberId}


        AND guest_id = #{guestId}
        AND member_id IS NULL

mapper.delete:
DELETE FROM cart
WHERE cart_id = #{cartId}


        AND member_id = #{memberId}


        AND guest_id = #{guestId}
        AND member_id IS NULL
